insert into public.diretorio_salas (nome,num,nome_en,nome_pt,descricao_en,descricao_pt,raridade_en,raridade_pt,custo_en,custo_pt,tipo_en,tipo_pt,categorias,diretorio,imagem,fonte,atualizado_em) values
('East Wing Hall',57,'East Wing Hall','East Wing Hall','This fenestrated hallway overlooks the east side of the estate grounds and is warmed in the early day by the light of the rising afternoon sun.','Este corredor com janelas dá para o lado leste dos jardins da propriedade e é aquecido no início do dia pela luz do sol da tarde nascente.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Hallway','Corredor (Hallway)',ARRAY['Hallway']::text[],'Hallways','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Hallways/East%20Wing%20Hall.png','https://blueprince.wiki.gg/wiki/East_Wing_Hall',now()),
('Corridor',58,'Corridor','Corridor','A long hall with two doors at either end that had been one of your uncle''s most frequently traveled rooms. Consequently, he had left strict instructions with the household staff that the doors of this corridor should never under any circumstance be locked.','Um longo corredor com duas portas nas extremidades que fora um dos cômodos mais frequentados por seu tio. Por consequência, ele havia deixado instruções estritas à equipe da casa de que as portas deste corredor jamais deveriam, sob nenhuma circunstância, ser trancadas.','Commonplace','Comum','None (no gem cost)','Nenhum (sem custo em gemas)','Hallway','Corredor (Hallway)',ARRAY['Hallway']::text[],'Hallways','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Hallways/Corridor.png','https://blueprince.wiki.gg/wiki/Corridor',now()),
('Passageway',59,'Passageway','Passageway','A long cramped series of unfinished passages used primarily by the servant staff to traverse the estate quickly.','Uma longa série de passagens apertadas e inacabadas, usadas principalmente pela equipe de criados para atravessar a propriedade rapidamente.','Commonplace','Comum','2 gems','2 gemas','Hallway','Corredor (Hallway)',ARRAY['Hallway']::text[],'Hallways','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Hallways/Passageway.png','https://blueprince.wiki.gg/wiki/Passageway',now()),
('Secret Passage',60,'Secret Passage','Secret Passage','A small "deadend" room with an ordinary bookcase, that exemplifies that the best means to escape the confinements of our world has always been through books.','Um pequeno cômodo "sem saída" com uma estante de livros comum, que exemplifica que o melhor meio de escapar das amarras do nosso mundo sempre foi através dos livros.','Unusual','Incomum','1 gem','1 gema','Hallway, "Dead End"','Corredor (Hallway), Beco sem saída (Dead End)',ARRAY['Hallway']::text[],'Hallways','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Hallways/Secret%20Passage.png','https://blueprince.wiki.gg/wiki/Secret_Passage',now()),
('Foyer',61,'Foyer','Foyer','The grand baroque hall of Mt. Holly is impressive to behold. This ornamented passage is flanked with marble pillars and bust statues of the more prominent figures of the Sinclair family legacy.','O grandioso saguão barroco de Mt. Holly é impressionante de se ver. Esta passagem ornamentada é ladeada por colunas de mármore e bustos das figuras mais proeminentes do legado da família Sinclair.','Unusual','Incomum','2 gems','2 gemas','Hallway','Corredor (Hallway)',ARRAY['Hallway']::text[],'Hallways','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Hallways/Foyer.png','https://blueprince.wiki.gg/wiki/Foyer',now()),
('Great Hall',62,'Great Hall','Great Hall','A room of many doors and even more choices. The Great Hall is unquestionably the largest hallway of the house but it is also the least useful, for the doors "lining" its walls are always locked. Perhaps for a reason.','Um cômodo de muitas portas e ainda mais escolhas. O Grande Salão é sem dúvida o maior corredor da casa, mas também é o menos útil, pois as portas que "revestem" suas paredes estão sempre trancadas. Talvez por um motivo.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Hallway','Corredor (Hallway)',ARRAY['Hallway']::text[],'Hallways','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Hallways/Great%20Hall.png','https://blueprince.wiki.gg/wiki/Great_Hall',now()),
('Terrace',63,'Terrace','Terrace','A terrace balcony overlooking the grounds providing an ideal spot for appreciating all the verdure and greenery that the estate offers.','Uma varanda em terraço com vista para os jardins, oferecendo um ponto ideal para apreciar toda a vegetação e o verde que a propriedade oferece.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Green Room, Dead End','Sala Verde (Green Room), Beco sem saída (Dead End)',ARRAY['Green Room']::text[],'Green Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Green%20Rooms/Terrace.png','https://blueprince.wiki.gg/wiki/Terrace',now()),
('Patio',64,'Patio','Patio','A roofed outdoor seating area located along the permieter of the estate. During the summer evenings, it is not unusual for the grill to be employed while entertaining acquaintances of a more informal nature.','Uma área de estar externa e coberta, localizada ao longo do perímetro da propriedade. Nas noites de verão, não é incomum que a churrasqueira seja usada ao entreter conhecidos de natureza mais informal.','Standard','Padrão','1 gem','1 gema','Spread, Green Room','Propagação (Spread), Sala Verde (Green Room)',ARRAY['Green Room']::text[],'Green Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Green%20Rooms/Patio.png','https://blueprince.wiki.gg/wiki/Patio',now()),
('Courtyard',65,'Courtyard','Courtyard','A charming spot granting guests a bit of fresh air and open skies within the privacy of the manor walls.','Um ponto charmoso que concede aos hóspedes um pouco de ar fresco e céu aberto dentro da privacidade das paredes da mansão.','Standard','Padrão','1 gem','1 gema','Green Room','Sala Verde (Green Room)',ARRAY['Green Room']::text[],'Green Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Green%20Rooms/Courtyard.png','https://blueprince.wiki.gg/wiki/Courtyard',now()),
('Cloister',66,'Cloister','Cloister','A covered walk and colonnade surrounding an enclosed and seemingly inaccessible garden. A solitary angelic statue in the center of the grassy patch provides this secluded court a hallowed atmosphere.','Um caminho coberto e uma colunata que cercam um jardim fechado e aparentemente inacessível. Uma solitária estátua angelical no centro do gramado confere a este pátio recluso uma atmosfera sagrada.','Unusual','Incomum','3 gems','3 gemas','Green Room','Sala Verde (Green Room)',ARRAY['Green Room']::text[],'Green Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Green%20Rooms/Cloister.png','https://blueprince.wiki.gg/wiki/Cloister',now()),
('Veranda',67,'Veranda','Veranda','This relaxing breezeway serves as an ideal spot for rocking chairs and lemonade.','Esta relaxante varanda arejada é o ponto ideal para cadeiras de balanço e limonada.','Unusual','Incomum','2 gems','2 gemas','Green Room','Sala Verde (Green Room)',ARRAY['Green Room']::text[],'Green Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Green%20Rooms/Veranda.png','https://blueprince.wiki.gg/wiki/Veranda',now()),
('Greenhouse',68,'Greenhouse','Greenhouse','This room is always warm as its glass walls and roof help to retain the sun''s rays. The gardener, however, should be scolded for the soil here is dry and the flower beds are devoid of all signs of life.','Este cômodo está sempre quente, pois suas paredes e teto de vidro ajudam a reter os raios do sol. O jardineiro, no entanto, merece uma repreensão, pois o solo aqui está seco e os canteiros de flores estão desprovidos de qualquer sinal de vida.','Standard','Padrão','1 gem','1 gema','Drafting, Green Room, Dead End','Sorteio (Drafting), Sala Verde (Green Room), Beco sem saída (Dead End)',ARRAY['Green Room']::text[],'Green Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Green%20Rooms/Greenhouse.png','https://blueprince.wiki.gg/wiki/Greenhouse',now()),
('Morning Room',69,'Morning Room','Morning Room','The best thing to go with breakfast is a morning newspaper and a coffee.','A melhor coisa para acompanhar o café da manhã é um jornal matinal e um café.','Rare','Raro','None (no gem cost)','Nenhum (sem custo em gemas)','Tomorrow, Green Room, Addition','Tomorrow, Sala Verde (Green Room), Adição (Addition)',ARRAY['Green Room']::text[],'Green Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Green%20Rooms/Morning%20Room.png','https://blueprince.wiki.gg/wiki/Morning_Room',now()),
('Secret Garden',70,'Secret Garden','Secret Garden','A floorplan so secretive it had been removed from the drafting pool to avoid anyone unwanted accidentally stumbling upon it. This secluded garden, flanked by a variety of Mora Jai fruit trees, has served as a private retreat to at least two other generations of Sinclairs.','Uma planta tão secreta que foi removida do baralho de sorteio para evitar que qualquer indesejado tropeçasse nela por acidente. Este jardim recluso, ladeado por uma variedade de árvores frutíferas de Mora Jai, serviu de refúgio privado a pelo menos duas outras gerações de Sinclairs.','Rare','Raro','None (no gem cost)','Nenhum (sem custo em gemas)','Spread, Green Room','Propagação (Spread), Sala Verde (Green Room)',ARRAY['Green Room']::text[],'Green Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Green%20Rooms/Secret%20Garden.png','https://blueprince.wiki.gg/wiki/Secret_Garden',now()),
('Commissary',71,'Commissary','Commissary','The staff commissary is always stocked with household goods and supplies at a reasonable cost. This provides the servants of the estate an invaluable service, especially to the live-in staff who may only expect to leave the property once or twice a month.','A cantina da equipe está sempre abastecida com produtos e suprimentos domésticos a um preço razoável. Isso oferece aos criados da propriedade um serviço inestimável, especialmente à equipe residente, que só pode esperar deixar a propriedade uma ou duas vezes por mês.','Standard','Padrão','1 gem','1 gema','Shop','Loja (Shop)',ARRAY['Shop']::text[],'Shops','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Shops/Commissary.png','https://blueprince.wiki.gg/wiki/Commissary',now()),
('Kitchen',72,'Kitchen','Kitchen','A standard kitchenette with all the typical amenities: a stove, refrigerator, oven and sink. This gallery is where the cooking staff prepares the daily cuisine that will be later served in the Dining Room.','Uma cozinha padrão com todas as comodidades habituais: fogão, geladeira, forno e pia. É nesta copa que a equipe de cozinha prepara a culinária diária que depois será servida na Sala de Jantar.','Commonplace','Comum','1 gem','1 gema','Shop','Loja (Shop)',ARRAY['Shop']::text[],'Shops','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Shops/Kitchen.png','https://blueprince.wiki.gg/wiki/Kitchen',now()),
('Locksmith',73,'Locksmith','Locksmith','Considering the amount of floor plans and different doors that can appear on any given day, it was only a matter of time before a fulltime locksmith service became an essential requisite on the estate.','Considerando a quantidade de plantas e de portas diferentes que podem surgir em um dado dia, era só uma questão de tempo até que um serviço de chaveiro em tempo integral se tornasse um requisito essencial na propriedade.','Unusual','Incomum','1 gem','1 gema','Shop, Dead End','Loja (Shop), Beco sem saída (Dead End)',ARRAY['Shop']::text[],'Shops','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Shops/Locksmith.png','https://blueprince.wiki.gg/wiki/Locksmith',now()),
('Showroom',74,'Showroom','Showroom','An array of jewelry display cabinets showcasing an impressive selection of high-priced items, each unique and one of a kind. This exclusive collection is not for the faint of purse.','Uma série de vitrines expondo joias, apresentando uma impressionante seleção de itens de alto valor, cada um único e exclusivo. Esta coleção exclusiva não é para os de bolso fraco.','Rare','Raro','2 gems','2 gemas','Shop','Loja (Shop)',ARRAY['Shop']::text[],'Shops','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Shops/Showroom.png','https://blueprince.wiki.gg/wiki/Showroom',now()),
('Laundry Room',75,'Laundry Room','Laundry Room','A standard hub of domestic toil complete with washers, dryers and a state of the art steampowered unit leveraging the newly installed steam ducts leading from the boiler room. Despite its innocent appearance, this inconspicuous space is rumored to launder more than just linen.','Um polo típico de labuta doméstica, completo com lavadoras, secadoras e uma unidade de última geração movida a vapor que aproveita os dutos de vapor recém-instalados vindos da sala das caldeiras. Apesar da aparência inocente, corre o boato de que este espaço discreto lava mais do que apenas roupa.','Rare','Raro','1 gem','1 gema','Shop, Dead End','Loja (Shop), Beco sem saída (Dead End)',ARRAY['Shop']::text[],'Shops','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Shops/Laundry%20Room.png','https://blueprince.wiki.gg/wiki/Laundry_Room',now()),
('Bookshop',76,'Bookshop','Bookshop','This cozy little bookstore is often tucked away in the more secluded corners of the estate, giving guests little opportunity to appreciate the curated selection of equally rare books it offers. Title purchased in the Bookshop will be automatically added to the Library''s book request form, which fittingly, is the only room in which this rare floorplan can be drawn.','Esta aconchegante livrariazinha costuma ficar escondida nos cantos mais reclusos da propriedade, dando aos hóspedes pouca oportunidade de apreciar a seleção curada de livros igualmente raros que oferece. Os títulos comprados na Livraria serão automaticamente adicionados ao formulário de requisição de livros da Biblioteca, que, convenientemente, é o único cômodo em que esta planta rara pode ser sorteada.','Rare','Raro','1 gem','1 gema','shop','Loja (Shop)',ARRAY['Shop']::text[],'Shops','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Shops/Bookshop.png','https://blueprince.wiki.gg/wiki/Bookshop',now()),
('The Armory',77,'The Armory','The Armory','A stone chamber fitted with ancient weapons and armor from the Second Era. This room appears to predate almost every other room in the house directory and may in fact be an authentic floorplan from one of the lost strongholds of Orinda Aries.','Uma câmara de pedra equipada com armas e armaduras antigas da Segunda Era. Este cômodo parece anteceder quase todos os outros do diretório da casa e pode, na verdade, ser uma planta autêntica de uma das fortalezas perdidas de Orinda Aries.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Shop, Blackprint','Loja (Shop), Blackprint (planta negra)',ARRAY['Shop']::text[],'Shops','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Shops/The%20Armory.png','https://blueprince.wiki.gg/wiki/The_Armory',now()),
('Gift Shop',78,'Gift Shop','Gift Shop','Thank you for visiting Mount Holly. We hope you enjoyed your stay here!','Obrigado por visitar Mount Holly. Esperamos que tenha aproveitado sua estadia aqui!','Rare','Raro','None (no gem cost)','Nenhum (sem custo em gemas)','Shop, Addition','Loja (Shop), Adição (Addition)',ARRAY['Shop']::text[],'Shops','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Shops/Gift%20Shop.png','https://blueprince.wiki.gg/wiki/Gift_Shop',now()),
('Lavatory',79,'Lavatory','Lavatory','A room one might go to great lengths to avoid showing guests despite them always probing for its location.','Um cômodo que se faria de tudo para evitar mostrar aos hóspedes, apesar de eles sempre indagarem por sua localização.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Red Room, Dead End','Sala Vermelha (Red Room), Beco sem saída (Dead End)',ARRAY['Red Room']::text[],'Red Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Red%20Rooms/Lavatory.png','https://blueprince.wiki.gg/wiki/Lavatory',now()),
('Chapel',80,'Chapel','Chapel','A private sacristy, as ornate as the most lavish rooms of the estate, is watched over by eight Ajeran Angels depicted in stained glass. This room was more a tribute to your uncle''s vanity than it was to his faith.','Uma sacristia privativa, tão ornamentada quanto os cômodos mais luxuosos da propriedade, é vigiada por oito Anjos Ajeranos retratados em vitrais. Este cômodo era mais um tributo à vaidade de seu tio do que à sua fé.','Commonplace','Comum','None (no gem cost)','Nenhum (sem custo em gemas)','Entry, Red Room','Entrada (Entry), Sala Vermelha (Red Room)',ARRAY['Red Room']::text[],'Red Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Red%20Rooms/Chapel.png','https://blueprince.wiki.gg/wiki/Chapel',now()),
('Maid''s Chamber',81,'Maid''s Chamber','Maid''s Chamber','A typical example of the accommodations for the live-in staff on the estate. It appears this particular bedroom belongs to one of the maids.','Um exemplo típico das acomodações da equipe residente da propriedade. Ao que parece, este quarto em particular pertence a uma das criadas.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Red Room, Bedroom','Sala Vermelha (Red Room), Quarto (Bedroom)',ARRAY['Red Room']::text[],'Red Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Red%20Rooms/Maid''s%20Chamber.png','https://blueprince.wiki.gg/wiki/Maid''s_Chamber',now()),
('Archives',82,'Archives','Archives','Countless shelves of documents and towering file cabinets make this otherwise immense space seem small and cramped. These archives contain almost a century of records and files pertaining to the Sinclair family''s numerous interests, many of which are sealed and unable to be accessed.','Incontáveis prateleiras de documentos e imponentes arquivos de aço fazem este espaço, por si só imenso, parecer pequeno e apertado. Estes arquivos contêm quase um século de registros e documentos referentes aos numerosos interesses da família Sinclair, muitos dos quais estão lacrados e inacessíveis.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Red Room','Sala Vermelha (Red Room)',ARRAY['Red Room']::text[],'Red Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Red%20Rooms/Archives.png','https://blueprince.wiki.gg/wiki/Archives',now()),
('Gymnasium',83,'Gymnasium','Gymnasium','A half-court intended for basketball and racquetball which is seldom used by anyone apart from the junior staff during their lunch hour. At least they did before Mrs. Babbage disallowed the practice after noticing how worn out staff members were after a game.','Uma quadra reduzida destinada a basquete e squash, raramente usada por alguém além da equipe júnior durante o horário de almoço. Ao menos era assim, antes de a Sra. Babbage proibir a prática ao notar como os funcionários ficavam esgotados depois de uma partida.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Entry, Red Room','Entrada (Entry), Sala Vermelha (Red Room)',ARRAY['Red Room']::text[],'Red Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Red%20Rooms/Gymnasium.png','https://blueprince.wiki.gg/wiki/Gymnasium',now()),
('Darkroom',84,'Darkroom','Darkroom','A room dedicated to photo processing, development and print-making. This room is outfitted with safelights which provide red illumination to which the photographic material is insensitive. However, due to a faulty installation the safelights often overload their circuit capacity and blow a fuse.','Um cômodo dedicado ao processamento, à revelação e à impressão de fotos. Este cômodo é equipado com lâmpadas de segurança que fornecem iluminação vermelha à qual o material fotográfico é insensível. No entanto, devido a uma instalação defeituosa, as lâmpadas de segurança costumam sobrecarregar a capacidade do circuito e queimar um fusível.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Red Room','Sala Vermelha (Red Room)',ARRAY['Red Room']::text[],'Red Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Red%20Rooms/Darkroom.png','https://blueprince.wiki.gg/wiki/Darkroom',now()) on conflict (nome) do update set num=excluded.num,nome_en=excluded.nome_en,nome_pt=excluded.nome_pt,descricao_en=excluded.descricao_en,descricao_pt=excluded.descricao_pt,raridade_en=excluded.raridade_en,raridade_pt=excluded.raridade_pt,custo_en=excluded.custo_en,custo_pt=excluded.custo_pt,tipo_en=excluded.tipo_en,tipo_pt=excluded.tipo_pt,categorias=excluded.categorias,diretorio=excluded.diretorio,imagem=excluded.imagem,fonte=excluded.fonte,atualizado_em=excluded.atualizado_em;
